#!/usr/bin/env python3
"""Stage source-bound G1 Gospel with the exact previously approved Card runtime."""
from datetime import datetime,timezone
import importlib.util,json,os,shutil,subprocess,sys
from pathlib import Path
from g1_evidence import ROOT,OUT,BUILD,STAGE,PRIOR,require,read,ref,digest,current_build,browser,preserved_cards
sys.path.insert(0,str(ROOT/'Tools/Web'))
from release_contract import ENCOUNTER,manifest_contract
spec=importlib.util.spec_from_file_location('g1_old_public_safety',ROOT/'Tools/Web/stage-luminous.py');SAFETY=importlib.util.module_from_spec(spec);spec.loader.exec_module(SAFETY)

def main():
 changed=current_build();reports=[browser(p)for p in ('Desktop720','Mobile844')];cards=preserved_cards()
 require(not subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True),'Commit validated source before staging')
 source=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
 require(not STAGE.exists() and not STAGE.is_symlink(),'Preserve prior stage; unique G1 output must not exist')
 prior=read(PRIOR/'build-manifest.json');STAGE.mkdir();(STAGE/'.firstgame-web-output').write_text('Generated by Tools/Autonomy/g1_stage.py\n')
 def copy(file,target):
  require(file.is_file() and not file.is_symlink(),'Only immutable ordinary files are staged');target.parent.mkdir(parents=True,exist_ok=True)
  try:os.link(file,target)
  except OSError:shutil.copyfile(file,target)
  require(digest(file)==digest(target),'Staged copy differs')
 for name in prior['files']:
  if name.startswith('games/path-of-dawn/') and '/ThirdParty/'not in name:continue
  SAFETY.safe_public(PRIOR/name,name);copy(PRIOR/name,STAGE/name)
 from nativity_release_evidence import runtime
 for name,file in runtime(BUILD/'PathOfDawn/Web').items():
  public='games/path-of-dawn/'+name;SAFETY.safe_public(file,public);copy(file,STAGE/public)
 files={p.relative_to(STAGE).as_posix():digest(p)for p in sorted(STAGE.rglob('*'))if p.is_file() and p.name!='.firstgame-web-output'}
 manifest={'releaseProfile':'autonomy-g1','currentTargets':['Web'],'createdUtc':datetime.now(timezone.utc).isoformat(),'publishReady':True,'gameRevisions':ENCOUNTER['revisions'],'contentVersions':ENCOUNTER['contents'],'sourceCommit':source,'sourceDirty':False,'files':files,'browserProfiles':['Desktop720','Mobile844'],'browserProfilesByGame':{'FantasyCards':['Desktop720','Mobile844'],'PathOfDawn':['Desktop720','Mobile844']},'browserReportRootsByGame':ENCOUNTER['reportRoots'],'currentBuilds':{'currentTargets':['Web'],'games':{'FantasyCards':cards,'PathOfDawn':changed}},'currentBrowserReports':{'FantasyCards':cards['browserReports'],'PathOfDawn':reports},'reusedBrowserEvidence':[cards],'incompleteBrowserRuns':[],'adjudicatedBrowserReports':[],'siteBudgetBytesIncludingManifest':985000000,'preservedPublic':{'manifest':ref(PRIOR/'build-manifest.json'),'audit':cards['priorPublicProof']['report'],'scope':'Prior complete stage retained byte-for-byte except changed Gospel runtime. Existing hero/notices/site CSS and Card files unchanged.'}}
 manifest_contract(manifest);(STAGE/'build-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
 total=sum(p.stat().st_size for p in STAGE.rglob('*')if p.is_file() and p.name!='.firstgame-web-output')
 require(total<985000000,'Complete site exceeds preserved985MB budget; no quality/content removal permitted')
 for name,h in prior['files'].items():
  if not(name.startswith('games/path-of-dawn/') and '/ThirdParty/'not in name):require(digest(STAGE/name)==h,'Unchanged preserved public byte differs')
 record={'status':'staged','sourceCommit':source,'files':len(files)+1,'bytesIncludingManifest':total,'manifest':ref(STAGE/'build-manifest.json'),'retainedCardProof':cards,'currentGospel':changed,'reports':reports};(OUT/'stage.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':'staged','source':source,'bytes':total,'stage':str(STAGE)}))

if __name__=='__main__':main()
